starter_code.Python:
def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

n = int(input())
print(factorial(n))

starter_code.C:
#include <stdio.h>
long long factorial(int n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}
int main(void) {
    int n; if (scanf("%d", &n) != 1) return 0;
    printf("%lld\n", factorial(n));
    return 0;
}

